export const DEEP_SPACE_CSS = `.dsb-space{position:absolute;inset:0;width:100%;height:100%;overflow:hidden;background:#030719;contain:strict;pointer-events:none;user-select:none}
.dsb-space .L{position:absolute;inset:0;width:100%;height:100%}
.dsb-space .defs{position:absolute;width:0;height:0}
.dsb-space .sd{position:absolute;top:0;left:0;width:200%;height:100%;will-change:transform;animation:sdrift linear infinite}
.dsb-space .sd .s{position:absolute;inset:0;width:100%;height:100%}
@keyframes sdrift{to{transform:translate3d(-50%,0,0)}}
.dsb-space .twa{will-change:opacity;animation:tw 5s ease-in-out infinite alternate}
.dsb-space .twb{will-change:opacity;animation:tw 8s ease-in-out -3s infinite alternate}
@keyframes tw{from{opacity:.2}to{opacity:1}}
.dsb-space .dr{will-change:transform;animation:dr 26s ease-in-out infinite alternate}
.dsb-space .d1{animation-name:dr2;animation-duration:33s}.d2{animation-name:dr3;animation-duration:39s}.d3{animation-name:dr4;animation-duration:30s}
@keyframes dr{to{transform:translate3d(10px,-8px,0)}}
@keyframes dr2{to{transform:translate3d(-9px,7px,0)}}
@keyframes dr3{to{transform:translate3d(8px,9px,0)}}
@keyframes dr4{to{transform:translate3d(-10px,-6px,0)}}
.dsb-space .nebL{will-change:transform;animation:nebl 90s ease-in-out infinite alternate}
@keyframes nebl{to{transform:translate3d(22px,-14px,0) scale(1.05)}}
.dsb-space .w{font-family:'Segoe UI','Noto Sans','Noto Sans Devanagari','Noto Sans Tamil','Noto Sans Bengali','Noto Sans Gujarati','Noto Sans Telugu','Noto Sans Kannada','Noto Sans Malayalam','Noto Sans Oriya','Noto Sans Gurmukhi','Noto Sans Arabic','Nirmala UI',system-ui,sans-serif;fill:#a9bfe8;text-anchor:start}
.dsb-space .fm{font-family:'Cambria Math','STIX Two Math','Times New Roman',serif;font-style:italic;fill:#9fb4e6;text-anchor:start}
.dsb-space .name{font-family:'Segoe UI',system-ui,sans-serif;font-weight:800;text-anchor:middle;fill:url(#nebfill);stroke:rgba(215,230,255,.75);stroke-width:.9;paint-order:stroke}
.dsb-space .brand{font-family:'Segoe UI',system-ui,sans-serif;font-weight:800;text-anchor:middle}
.dsb-space .a1{animation:a1 12s ease-in-out infinite alternate}.a2{animation:a2 16s ease-in-out infinite alternate}
@keyframes a1{from{transform:translateX(-36px)}to{transform:translateX(36px)}}
@keyframes a2{from{transform:translateX(40px)}to{transform:translateX(-40px)}}
.dsb-space .pulse{transform-box:fill-box;transform-origin:center;animation:pulse 8s ease-in-out infinite}
@keyframes pulse{0%,100%{transform:scale(.92);opacity:.7}50%{transform:scale(1.08);opacity:1}}
.dsb-space .logo-float{animation:lf 6s ease-in-out infinite alternate}
@keyframes lf{from{transform:translateY(0)}to{transform:translateY(-9px)}}
.dsb-space .shoot{opacity:0;animation:shoot 14s linear infinite}
@keyframes shoot{0%{transform:translateX(0);opacity:0}1%{opacity:1}8%{transform:translateX(520px);opacity:0}100%{transform:translateX(520px);opacity:0}}
.dsb-space .const{animation:cons 9s ease-in-out infinite}
@keyframes cons{0%,100%{opacity:.25}50%{opacity:1}}
.dsb-space .spin,.dsb-space .spin2{transform-box:fill-box;transform-origin:center;animation:spin 24s linear infinite}
.dsb-space .spin2{animation-duration:70s}.galaxy{transform-box:fill-box;transform-origin:center;animation:spin 220s linear infinite}
@keyframes spin{to{transform:rotate(360deg)}}
.dsb-space .neb{animation:none}
.dsb-space .tkw{position:absolute;left:0;width:100%;overflow:hidden;-webkit-mask-image:linear-gradient(90deg,transparent,#000 8%,#000 92%,transparent);mask-image:linear-gradient(90deg,transparent,#000 8%,#000 92%,transparent)}
.dsb-space .tk{display:block;will-change:transform}
@keyframes tks{to{transform:translate3d(-50%,0,0)}}
.dsb-space .gA,.dsb-space .gB,.dsb-space .gC,.dsb-space .city{transform-box:fill-box;transform-origin:center;animation-timing-function:ease-in-out;animation-iteration-count:infinite;animation-direction:alternate}
.dsb-space .gA{animation-name:grA;animation-duration:11s}
.dsb-space .gB{animation-name:grB;animation-duration:14s}
.dsb-space .gC{animation-name:grC;animation-duration:17s}
.dsb-space .city{animation-name:grB}.city.c0{animation-duration:15s}.city.c1{animation-duration:19s}.city.c2{animation-duration:23s}
@keyframes grA{from{transform:scale(.88)}to{transform:scale(1.2)}}
@keyframes grB{from{transform:translate3d(-7px,5px,0) scale(.95)}to{transform:translate3d(7px,-5px,0) scale(1.1)}}
@keyframes grC{from{transform:translate3d(6px,6px,0) scale(1.12)}to{transform:translate3d(-6px,-6px,0) scale(.9)}}
@media (prefers-reduced-motion:reduce){.dsb-space *{animation:none!important}}`

